@Testcontainers class RedactionPreviewIT {
 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:74935e72241653ca55e0414067e6d8763aceb8a810eb51b452253ec3dcfc4336").asCompatibleSubstituteFor("postgres"));
 static final Instant NOW=Instant.parse("2026-10-22T12:00:00Z");static final Clock CLOCK=Clock.fixed(NOW,ZoneOffset.UTC);static final UuidGenerator IDS=new UuidGenerator(CLOCK);static JdbcTemplate owner,jdbc;static TransactionTemplate ownerTx,tx,snapshot;static JdbcPrivateCaseReview review;static JdbcRedactionPreviews previews;
 static Timestamp at(Instant t){return Timestamp.from(t);}
 @BeforeAll static void setup()throws Exception{
  MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());owner=new JdbcTemplate(ds);ownerTx=new TransactionTemplate(new DataSourceTransactionManager(ds));owner.execute("CREATE ROLE redaction_runtime NOLOGIN");owner.execute("GRANT USAGE ON SCHEMA public TO redaction_runtime");owner.execute("GRANT SELECT ON account_identity,platform_account,application_session,application_session_identity,organization,privacy_case_metadata TO redaction_runtime");owner.execute("GRANT UPDATE(id) ON account_identity,application_session,organization TO redaction_runtime");owner.execute("GRANT INSERT ON audit_event TO redaction_runtime");for(String file:List.of("private-review-grants.sql","redaction-preview-grants.sql"))owner.execute(java.nio.file.Files.readString(java.nio.file.Path.of("audit",file)).replace("__RUNTIME_ROLE__","redaction_runtime"));
  var restricted=new DelegatingDataSource(ds){@Override public Connection getConnection()throws SQLException{var c=super.getConnection();try(var s=c.createStatement()){s.execute("SET ROLE redaction_runtime");s.execute("SET lock_timeout='2s'");}return c;}};jdbc=new JdbcTemplate(restricted);tx=new TransactionTemplate(new DataSourceTransactionManager(restricted));tx.setTimeout(10);snapshot=new TransactionTemplate(new DataSourceTransactionManager(restricted));snapshot.setTimeout(10);snapshot.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);review=new JdbcPrivateCaseReview(jdbc,CLOCK,IDS);previews=new JdbcRedactionPreviews(jdbc,CLOCK,IDS,review);new RedactionPreviewConfiguration().redactionPreviewPrivilegeGate(jdbc,new org.springframework.mock.env.MockEnvironment().withProperty("identity.http.enabled","true"));
 }
 record Fixture(UUID source,UUID organization,String country,UUID subject,UUID owner,PrivateCaseReview.Actor actor){}
 Fixture fixture(String country,String type,String role,String kind){UUID organization=IDS.next(),subject=IDS.next(),ownerId=role.equals("OWNER")?subject:IDS.next(),actor=IDS.next(),session=IDS.next(),source=IDS.next();ownerTx.executeWithoutResult(s->{
  for(UUID id:new LinkedHashSet<>(List.of(subject,ownerId,actor)))owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state,created_at,updated_at) VALUES(?,?,?,true,'SENSITIVE-SOURCE-ČAJ','ACTIVE',?,?)",id,id.equals(actor)?"PLATFORM_ADMIN":"BUSINESS",id+"@example.com",at(NOW),at(NOW));
  owner.update("INSERT INTO platform_account(id) VALUES(?)",actor);owner.update("INSERT INTO organization(id,type,country,currency,display_name,legal_name,registration_identifier,address_line1,address_city,address_postal_code,address_country,default_language,state,owner_account_id) VALUES(?,?,?,?,'Synthetic','Synthetic',?,'Synthetic','Synthetic','11000',?,'en','ACTIVE',?)",organization,type,country,country.equals("RS")?"RSD":"BAM",organization.toString(),country,ownerId);owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'OWNER')",ownerId,organization);if(!subject.equals(ownerId))owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,?)",subject,organization,role);
  owner.execute("SET LOCAL narudzbine.operator_change_reference='SYNTHETIC-REDACTION-TEST'");owner.update("INSERT INTO privacy_operator(account_id,created_at) VALUES(?,?)",actor,at(NOW));owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',?,'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,actor,HexFormat.of().parseHex(IndependentEvidence.hash(session.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8))),at(NOW),at(NOW),at(NOW.plusSeconds(43200)),at(NOW));owner.update("INSERT INTO privacy_case(id,requester_id,organization_id,country,kind,private_reason,created_at) VALUES(?,?,?,?,?,'PRIVATE-REQUEST-SENTINEL',?)",source,subject,organization,country,kind,at(NOW));
 });return new Fixture(source,organization,country,subject,ownerId,new PrivateCaseReview.Actor(actor,session,"NATIVE"));}
 void guards(Fixture f){jdbc.queryForList("SELECT id FROM organization WHERE id=? FOR UPDATE",f.organization());jdbc.queryForList("SELECT id FROM account_identity WHERE id=? FOR UPDATE",f.actor().account());jdbc.queryForList("SELECT id FROM application_session WHERE id=? FOR UPDATE",f.actor().session());}
 PrivateCaseReview.Access authorize(Fixture f){return tx.execute(s->{guards(f);return review.authorize(f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),f.actor(),new PrivateCaseReview.Context("Synthetic preview purpose","SYN-PREVIEW"));});}
 RedactionPreviews.Preview inspect(Fixture f,PrivateCaseReview.Access a){return snapshot.execute(s->{guards(f);return previews.inspect(a);});}
 long audits(Fixture f){return owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='PRIVACY_REDACTION_PREVIEWED'",Long.class,f.source());}
 @Test void bothCountriesAndTypesReturnExactNonContentCountsAndKeepOriginalState(){for(String country:List.of("RS","BA"))for(String type:List.of("BUYER","VENDOR")){var f=fixture(country,type,"OWNER","REDACTION");UUID contact=IDS.next();owner.update("INSERT INTO business_contact(id,organization_id,label,contact_name,contact_phone,contact_email,state,created_at,updated_at) VALUES(?,?,'Private','SENSITIVE-SOURCE-ČAJ','+381111',?,'ACTIVE',?,?)",contact,f.organization(),f.subject()+"@example.com",at(NOW),at(NOW));var original=owner.queryForMap("SELECT to_jsonb(a)::text AS original FROM account_identity a WHERE id=?",f.subject());var result=inspect(f,authorize(f));assertThat(result.subjectAccountId()).isEqualTo(f.subject());assertThat(result.country()).isEqualTo(country);assertThat(result.fieldActions()).hasSize(5);assertThat(result.retainedFamilies()).filteredOn(r->r.family().equals("ORGANIZATION_CONTACTS")).singleElement().satisfies(r->{assertThat(r.relatedRecords()).isEqualTo(1);assertThat(r.reviewCode()).isEqualTo("EXPLICIT_SUBJECT_ASSOCIATION_REQUIRED");assertThat(r.sourceScope()).isEqualTo("ORGANIZATION_INVENTORY");});assertThat(result.retainedFamilies()).filteredOn(r->r.family().equals("PROVIDER_AND_DELIVERY_COPIES")).singleElement().satisfies(r->assertThat(r.relatedRecords()).isNull());assertThat(result.blockers()).contains("OWNER_TRANSFER_OR_REVIEW_REQUIRED","AUTHENTICATION_CONTAINMENT_REQUIRED","EXECUTION_NOT_AVAILABLE");assertThat(result.executionAvailable()).isFalse();String body=tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(result);assertThat(body).doesNotContain("SENSITIVE-SOURCE-ČAJ","PRIVATE-REQUEST-SENTINEL","@example.com","+381111");assertThat(owner.queryForMap("SELECT to_jsonb(a)::text AS original FROM account_identity a WHERE id=?",f.subject())).isEqualTo(original);assertThat(owner.queryForObject("SELECT count(*) FROM privacy_fulfillment WHERE case_id=?",Integer.class,f.source())).isZero();assertThat(audits(f)).isEqualTo(1);}}
 @Test void repeatedAssessmentUsesCurrentMetadataWithoutExecutionOrCreationReceipt(){var f=fixture("RS","BUYER","ADMIN","REDACTION");var a=authorize(f);assertThat(inspect(f,a).blockers()).contains("AUTHENTICATION_CONTAINMENT_REQUIRED");owner.update("UPDATE account_identity SET state='DEACTIVATED',revision=revision+1 WHERE id=?",f.subject());assertThat(inspect(f,authorize(f)).blockers()).doesNotContain("AUTHENTICATION_CONTAINMENT_REQUIRED","OWNER_TRANSFER_OR_REVIEW_REQUIRED");assertThat(audits(f)).isEqualTo(2);assertThat(owner.queryForObject("SELECT count(*) FROM privacy_export_job WHERE case_id=?",Integer.class,f.source())).isZero();}
 @Test void closedOrganizationDoesNotEvadeSoleOwnerOrAuthenticationContainment(){var f=fixture("BA","BUYER","OWNER","REDACTION");owner.update("UPDATE organization SET state='CLOSED',revision=revision+1 WHERE id=?",f.organization());assertThat(inspect(f,authorize(f)).blockers()).contains("OWNER_TRANSFER_OR_REVIEW_REQUIRED","AUTHENTICATION_CONTAINMENT_REQUIRED");}
 @Test void wrongKindWrongNonceDifferentActorAndScopeFailBeforePreviewAudit(){var f=fixture("RS","BUYER","ADMIN","EXPORT");assertThatThrownBy(()->inspect(f,authorize(f))).isInstanceOf(PrivacyFailure.class);assertThat(audits(f)).isZero();var own=fixture("RS","BUYER","ADMIN","REDACTION");var a=authorize(own);var badNonce=new PrivateCaseReview.Access(a.id(),a.caseId(),a.target(),a.actor(),new byte[32],a.expires());assertThatThrownBy(()->inspect(own,badNonce)).isInstanceOf(PrivacyFailure.class);var foreign=fixture("BA","VENDOR","ADMIN","REDACTION");var changed=new PrivateCaseReview.Access(a.id(),a.caseId(),new PrivateCaseReview.Target(foreign.organization(),foreign.country()),a.actor(),a.nonce(),a.expires());assertThatThrownBy(()->inspect(own,changed)).isInstanceOf(PrivacyFailure.class);assertThat(audits(own)).isZero();}
 @Test void creatingTransactionCannotReadAndRollbackItsOnlyPermit(){var f=fixture("RS","VENDOR","ADMIN","REDACTION");tx.executeWithoutResult(s->{guards(f);var a=review.authorize(f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),f.actor(),new PrivateCaseReview.Context("Synthetic","SYN"));assertThatThrownBy(()->previews.inspect(a)).isInstanceOf(PrivacyFailure.class);s.setRollbackOnly();});assertThat(audits(f)).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM privacy_review_access WHERE case_id=?",Integer.class,f.source())).isZero();}
 @Test void revokedQualificationSessionAndEpochInvalidatePreviouslyCommittedPermit(){for(String mutation:List.of("qualification","session","epoch")){var f=fixture("BA","VENDOR","ADMIN","REDACTION");var a=authorize(f);if(mutation.equals("qualification"))ownerTx.executeWithoutResult(s->{owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-REVOKE'");owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",f.actor().account());});if(mutation.equals("session"))owner.update("UPDATE application_session SET revoked_at=? WHERE id=?",at(NOW),f.actor().session());if(mutation.equals("epoch"))owner.update("UPDATE account_identity SET security_epoch=security_epoch+1 WHERE id=?",f.actor().account());assertThatThrownBy(()->inspect(f,a)).isInstanceOf(PrivacyFailure.class);assertThat(audits(f)).isZero();}}
 @Test void expiredPermitAndAuditWriteFailureNeverReturnAResult(){var f=fixture("RS","BUYER","ADMIN","REDACTION");var a=authorize(f);Clock later=Clock.fixed(NOW.plusSeconds(60),ZoneOffset.UTC);var expired=new JdbcRedactionPreviews(jdbc,later,new UuidGenerator(later),new JdbcPrivateCaseReview(jdbc,later,new UuidGenerator(later)));assertThatThrownBy(()->snapshot.execute(s->{guards(f);return expired.inspect(a);})).isInstanceOf(PrivacyFailure.class);owner.execute("REVOKE INSERT ON audit_event FROM redaction_runtime");try{assertThatThrownBy(()->inspect(f,a)).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{owner.execute("GRANT INSERT ON audit_event TO redaction_runtime");}assertThat(audits(f)).isZero();}
 @Test void rawSourcesAndExecutionRemainDenied(){for(String sql:List.of("SELECT * FROM privacy_case","SELECT * FROM audit_event","SELECT * FROM purchase_order","SELECT * FROM business_contact","UPDATE privacy_case SET kind='EXPORT'","DELETE FROM privacy_case","SELECT inspect_redaction_preview(NULL,NULL,NULL,NULL,NULL,now())")){if(sql.startsWith("SELECT inspect")){assertThat(jdbc.queryForList(sql)).isEmpty();}else assertThatThrownBy(()->jdbc.execute(sql)).isInstanceOf(org.springframework.dao.DataAccessException.class);}assertThat(owner.queryForObject("SELECT NOT EXISTS(SELECT 1 FROM pg_proc p,LATERAL aclexplode(p.proacl) a WHERE p.oid='inspect_redaction_preview(uuid,bytea,uuid,uuid,text,timestamptz)'::regprocedure AND a.grantee=0 AND a.privilege_type='EXECUTE')",Boolean.class)).isTrue();}
 @Test void heldEvidenceIsReportedWithoutReleasingOrChangingIt(){var f=fixture("BA","BUYER","ADMIN","REDACTION");@SuppressWarnings("unchecked") ObjectProvider<ResourceRevisions> revisions=mock(ObjectProvider.class);when(revisions.getObject()).thenReturn(new ResourceRevisions(new byte[32]));var holds=new JdbcRetentionHolds(owner,new JdbcPrivateCaseReview(owner,CLOCK,IDS),CLOCK,IDS,revisions);UUID hold=IDS.next();var view=ownerTx.execute(s->holds.activate(f.actor(),f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),hold,new RetentionHolds.Context("Synthetic hold","SYN-HOLD")));try{assertThat(inspect(f,authorize(f)).blockers()).contains("HOLD_ACTIVE");assertThat(owner.queryForObject("SELECT state FROM retention_hold WHERE id=?",String.class,hold)).isEqualTo("ACTIVE");}finally{ownerTx.executeWithoutResult(s->holds.release(f.actor(),f.source(),hold,view.revision(),new RetentionHolds.Context("Synthetic release","SYN-RELEASE")));}}
 @Test void repeatableReadDoesNotMixALaterCommittedAuditIntoTheSameAssessment()throws Exception{var f=fixture("RS","BUYER","ADMIN","REDACTION");var a=authorize(f);var ready=new CountDownLatch(1);var resume=new CountDownLatch(1);try(var executor=Executors.newSingleThreadExecutor()){var pending=executor.submit(()->snapshot.execute(s->{guards(f);ready.countDown();try{if(!resume.await(5,TimeUnit.SECONDS))throw new IllegalStateException("Synthetic wait timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return previews.inspect(a);}));assertThat(ready.await(5,TimeUnit.SECONDS)).isTrue();try{owner.update("INSERT INTO audit_event(id,actor_type,actor_id,organization_id,country,action,resource_type,resource_id,outcome,request_id,occurred_at,changed_fields) VALUES(?,'BUSINESS',?,?,?,'ACCOUNT_LANGUAGE_CHANGED','ACCOUNT',?,'SUCCESS',?,?,ARRAY['languageOverride'])",IDS.next(),f.subject(),f.organization(),f.country(),f.subject(),IDS.next(),at(NOW));}finally{resume.countDown();}var first=pending.get(10,TimeUnit.SECONDS);assertThat(first.retainedFamilies()).filteredOn(r->r.family().equals("ATTRIBUTABLE_AUDIT_ROWS")).singleElement().satisfies(r->assertThat(r.relatedRecords()).isZero());assertThat(inspect(f,authorize(f)).retainedFamilies()).filteredOn(r->r.family().equals("ATTRIBUTABLE_AUDIT_ROWS")).singleElement().satisfies(r->assertThat(r.relatedRecords()).isEqualTo(1));}}

 @Test void oversizedAssessmentFailsCompletelyAndPreservesOnlyPriorAuthorization(){var f=fixture("RS","VENDOR","ADMIN","REDACTION");owner.update("INSERT INTO business_contact(id,organization_id,label,contact_name,contact_phone,state,created_at,updated_at) SELECT format('019a0000-0000-7000-8000-%s',lpad(to_hex(n),12,'0'))::uuid,?,'Synthetic','Synthetic','+381111','ARCHIVED',?,? FROM generate_series(1,100001)n",f.organization(),at(NOW),at(NOW));var a=authorize(f);assertThatThrownBy(()->inspect(f,a)).isInstanceOf(PrivacyFailure.class).extracting(e->((PrivacyFailure)e).code()).isEqualTo("PREVIEW_TOO_LARGE");assertThat(audits(f)).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM privacy_review_access WHERE case_id=?",Integer.class,f.source())).isEqualTo(1);}
 @Test void sourceLockTimeoutReturnsNoPartialAssessment()throws Exception{var f=fixture("BA","BUYER","ADMIN","REDACTION");var a=authorize(f);try(var connection=owner.getDataSource().getConnection();var statement=connection.createStatement()){connection.setAutoCommit(false);statement.execute("LOCK TABLE business_contact IN ACCESS EXCLUSIVE MODE");assertThatThrownBy(()->inspect(f,a)).isInstanceOf(org.springframework.dao.DataAccessException.class);connection.rollback();}assertThat(audits(f)).isZero();assertThat(inspect(f,a).subjectAccountId()).isEqualTo(f.subject());}

 @Test void authorizationSourceHelperCannotBeAttachedOrAbusedAfterAccidentalRegrant()throws Exception{try(var connection=jdbc.getDataSource().getConnection();var statement=connection.createStatement()){statement.execute("CREATE TEMP TABLE fake_authorization(id uuid)");assertThatThrownBy(()->statement.execute("CREATE TRIGGER fake BEFORE INSERT ON fake_authorization FOR EACH ROW EXECUTE FUNCTION protect_privacy_review_access()")).isInstanceOf(SQLException.class).hasMessageContaining("permission denied");owner.execute("GRANT EXECUTE ON FUNCTION protect_privacy_review_access() TO redaction_runtime");try{assertThatThrownBy(()->new RedactionPreviewConfiguration().redactionPreviewPrivilegeGate(jdbc,new org.springframework.mock.env.MockEnvironment().withProperty("identity.http.enabled","true"))).isInstanceOf(IllegalStateException.class);statement.execute("CREATE TRIGGER fake BEFORE INSERT ON fake_authorization FOR EACH ROW EXECUTE FUNCTION protect_privacy_review_access()");assertThatThrownBy(()->statement.execute("INSERT INTO fake_authorization VALUES('"+IDS.next()+"')")).isInstanceOf(SQLException.class).hasMessageContaining("Original review authorization source required");}finally{owner.execute("REVOKE EXECUTE ON FUNCTION protect_privacy_review_access() FROM redaction_runtime");}}}

}
